const setStructureAssignment = `-- name: SetStructureAssignment :execrows
INSERT INTO company_member_assignments(account_id,member_id,office_id,group_id)
SELECT $1,m.id,
 (SELECT o.id FROM company_offices o WHERE o.account_id=$1 AND o.uuid=$2::uuid),
 (SELECT id FROM company_groups WHERE account_id=$1 AND uuid=$3::uuid)
FROM account_members m JOIN users u ON u.id=m.user_id WHERE m.account_id=$1 AND u.uuid=$4
AND ($2::uuid IS NULL OR EXISTS(SELECT 1 FROM company_offices o WHERE o.account_id=$1 AND o.uuid=$2::uuid))
AND ($3::uuid IS NULL OR EXISTS(SELECT 1 FROM company_groups g WHERE g.account_id=$1 AND g.uuid=$3::uuid))
ON CONFLICT(member_id) DO UPDATE SET office_id=excluded.office_id,group_id=excluded.group_id
`

type SetStructureAssignmentParams struct {
	AccountID  int64       `json:"account_id"`
	OfficeUuid pgtype.UUID `json:"office_uuid"`
	GroupUuid  pgtype.UUID `json:"group_uuid"`
	UserUuid   uuid.UUID   `json:"user_uuid"`
}

func (q *Queries) SetStructureAssignment(ctx context.Context, arg SetStructureAssignmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, setStructureAssignment,
		arg.AccountID,
		arg.OfficeUuid,
		arg.GroupUuid,
		arg.UserUuid,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

